{"command":"python3 - <<'PY'
import re
p='src/semver.js'
s=open(p).read()
s=s.replace("""export function parseRange(text) {
  throw new Error('not implemented');
}""","""export function parseRange(text) {
  const fail = () => new ResolveError('BAD_RANGE', `invalid range: ${text}`);
  if (typeof text !== 'string') throw fail();
  const trimmed = text.trim();
  if (trimmed === '') throw fail();
  const parts = trimmed.split(/\\s+/);
  if (parts.includes('*')) {
    if (parts.length !== 1) throw fail();
    return [];
  }
  const comparators = [];
  for (const part of parts) {
    let match = /^(>=|<=|>|<|=)(.+)$/.exec(part);
    if (match !== null) {
      let parsed;
      try {
        parseVersion(match[2]);
      } catch {
        throw fail();
      }
      comparators.push({ operator: match[1], version: match[2] });
      continue;
    }
    match = /^([\\^~])(.+)$/.exec(part);
    if (match !== null) {
      let parsed;
      try {
        parsed = parseVersion(match[2]);
      } catch {
        throw fail();
      }
      const { major, minor, patch } = parsed;
      let upper;
      if (match[1] === '~') {
        upper = `${major}.${minor + 1}.0`;
      } else if (major !== 0) {
        upper = `${major + 1}.0.0`;
      } else if (minor !== 0) {
        upper = `0.${minor + 1}.0`;
      } else {
        upper = `0.0.${patch + 1}`;
      }
      comparators.push({ operator: '>=', version: match[2] });
      comparators.push({ operator: '<', version: upper });
      continue;
    }
    try {
      parseVersion(part);
    } catch {
      throw fail();
    }
    comparators.push({ operator: '=', version: part });
  }
  return comparators;
}""")
s=s.replace("""export function satisfies(version, range) {
  throw new Error('not implemented');
}""","""export function satisfies(version, range) {
  parseVersion(version);
  const comparators = parseRange(range);
  return comparators.every((comparator) => {
    const order = compareVersions(version, comparator.version);
    switch (comparator.operator) {
      case '>=':
        return order >= 0;
      case '<=':
        return order <= 0;
      case '>':
        return order > 0;
      case '<':
        return order < 0;
      default:
        return order === 0;
    }
  });
}""")
s=s.replace("""export function maxSatisfying(versions, range) {
  throw new Error('not implemented');
}""","""export function maxSatisfying(versions, range) {
  if (!Array.isArray(versions)) throw new ResolveError('BAD_VERSION', `invalid version: ${versions}`);
  parseRange(range);
  let best = null;
  for (const version of versions) {
    if (!satisfies(version, range)) continue;
    if (best === null || compareVersions(version, best) > 0) best = version;
  }
  return best;
}""")
open(p,'w').write(s)
PY
echo done"}

