export function parseRange(text) {
  const fail = () => new ResolveError('BAD_RANGE', `invalid range: ${text}`);
  if (typeof text !== 'string') throw fail();
  const trimmed = text.trim();
  if (trimmed === '') throw fail();
  const parts = trimmed.split(/\s+/);
  if (parts.includes('*')) {
    if (parts.length !== 1) throw fail();
    return [];
  }
  const comparators = [];
  for (const part of parts) {
    let match = /^(>=|<=|>|<|=)(.+)$/.exec(part);
    if (match !== null) {
      try {
        parseVersion(match[2]);
      } catch {
        throw fail();
      }
      if (match[1] === '=') comparators.push({ operator: '=', version: match[2] });
      else comparators.push({ operator: match[1], version: match[2] });
      continue;
    }
    match = /^([\^~])(.+)$/.exec(part);
    if (match !== null) {
      let parsed;
      try {
        parsed = parseVersion(match[2]);
      } catch {
        throw fail();
      }
      const { major, minor, patch } = parsed;
      let upper;
      if (match[1] === '~') upper = `${major}.${minor + 1}.0`;
      else if (major !== 0) upper = `${major + 1}.0.0`;
      else if (minor !== 0) upper = `0.${minor + 1}.0`;
      else upper = `0.0.${patch + 1}`;
      comparators.push({ operator: '>=', version: match[2] });
      comparators.push({ operator: '<', version: upper });
      continue;
    }
    try {
      parseVersion(part);
    } catch {
      throw fail();
    }
    comparators.push({ operator: '=', version: part });
  }
  return comparators;
}

